// Parse document processing request with enhanced validation
const documentId = $json.documentId;
const customerId = $json.customerId;
const widgetId = $json.widgetId;
const filename = $json.filename;
const fileUrl = $json.fileUrl;
const fileType = $json.fileType;
const fileSize = $json.fileSize || 0;

// Enhanced validation
if (!documentId || !customerId || !fileUrl) {
  throw new Error('Missing required fields: documentId, customerId, or fileUrl');
}

// File size validation (max 50MB)
if (fileSize > 50 * 1024 * 1024) {
  throw new Error('File too large. Maximum size is 50MB.');
}

// Determine processing strategy based on file type
let processingStrategy = 'text';
let extractionMethod = 'simple';

if (fileType.includes('pdf')) {
  processingStrategy = 'pdf';
  extractionMethod = 'pdf-parse';
} else if (fileType.includes('word') || fileType.includes('docx')) {
  processingStrategy = 'docx';
  extractionMethod = 'mammoth';
} else if (fileType.includes('text') || fileType.includes('markdown')) {
  processingStrategy = 'text';
  extractionMethod = 'direct';
} else {
  throw new Error(`Unsupported file type: ${fileType}`);
}

// Enhanced chunking parameters
const chunkingConfig = {
  chunkSize: 1000,        // characters per chunk
  chunkOverlap: 200,      // overlap between chunks
  minChunkSize: 100,      // minimum viable chunk size
  maxChunkSize: 1500,     // maximum chunk size
  preserveStructure: true, // try to preserve document structure
  language: 'turkish'     // language-specific processing
};

return [{
  json: {
    documentId,
    customerId,
    widgetId: widgetId || null,
    filename,
    fileUrl,
    fileType,
    fileSize,
    processingStrategy,
    extractionMethod,
    chunkingConfig,
    startTime: Date.now(),
    processingVersion: '2.0'
  }
}];

// Enhanced text processing with quality validation
const extractionResult = $json;
const documentInfo = $('Parse Document Request').item(0).json;

// Get extracted text and metadata
const extractedText = extractionResult.extractedText || '';
const pageCount = extractionResult.pageCount || 1;
const wordCount = extractionResult.wordCount || 0;
const extractionQuality = extractionResult.quality || 'unknown';
const detectedLanguage = extractionResult.detectedLanguage || 'tr';

// Enhanced validation
if (!extractedText || extractedText.trim().length < 50) {
  throw new Error(`Text extraction failed or document is too short. Length: ${extractedText.length}`);
}

// Quality check
if (extractionQuality === 'poor') {
  console.warn('Poor extraction quality detected:', {
    documentId: documentInfo.documentId,
    filename: documentInfo.filename,
    textLength: extractedText.length
  });
}

// Enhanced text cleaning for Turkish content
const cleanedText = extractedText
  // Normalize whitespace
  .replace(/\s+/g, ' ')
  // Remove control characters but preserve Turkish characters
  .replace(/[\x00-\x1F\x7F-\x9F]/g, '')
  // Clean up punctuation spacing
  .replace(/\s+([.,!?;:])/g, '$1')
  // Fix Turkish character encoding issues
  .replace(/Ã§/g, 'ç')
  .replace(/Ä±/g, 'ı')
  .replace(/Å/g, 'ş')
  .replace(/Ã¼/g, 'ü')
  .replace(/Ã¶/g, 'ö')
  .replace(/Äÿ/g, 'ğ')
  // Remove excessive punctuation
  .replace(/([.!?])\1{2,}/g, '$1')
  .trim();

// Calculate enhanced chunk parameters
const config = documentInfo.chunkingConfig;
const estimatedChunks = Math.ceil(cleanedText.length / (config.chunkSize - config.chunkOverlap));

// Text quality metrics
const qualityMetrics = {
  averageWordLength: cleanedText.split(' ').reduce((acc, word) => acc + word.length, 0) / wordCount,
  sentenceCount: (cleanedText.match(/[.!?]+/g) || []).length,
  turkishCharacterRatio: (cleanedText.match(/[çğıöşüÇĞIÖŞÜ]/g) || []).length / cleanedText.length,
  digitRatio: (cleanedText.match(/\d/g) || []).length / cleanedText.length
};

return [{
  json: {
    ...documentInfo,
    extractedText: cleanedText,
    textLength: cleanedText.length,
    pageCount,
    wordCount,
    extractionQuality,
    detectedLanguage,
    qualityMetrics,
    estimatedChunks,
    extractionTime: Date.now() - documentInfo.startTime,
    processingStatus: 'text_extracted'
  }
}];

// Enhanced intelligent document chunking
const data = $json;
const text = data.extractedText;
const config = data.chunkingConfig;

// Advanced chunking function with structure preservation
function intelligentChunking(text, config) {
  const chunks = [];
  let currentPos = 0;
  let chunkIndex = 0;

  // Turkish sentence endings and paragraph markers
  const sentenceEndings = ['.', '!', '?', '…'];
  const paragraphMarkers = ['\n\n', '\r\n\r\n'];
  const structuralMarkers = {
    heading: /^(\d+\.\s|[A-ZÜÇĞIÖŞ][A-ZÜÇĞIÖŞa-züçğıöş\s]+:)|(BÖLÜM|MADDE|BAŞLIK)/,
    list: /^[\s]*[-•*]\s|^[\s]*\d+[.)]/,
    table: /\|.*\|/
  };

  function findBestChunkBoundary(text, startPos, idealEnd) {
    const searchEnd = Math.min(idealEnd + config.chunkSize * 0.3, text.length);
    const searchStart = Math.max(idealEnd - config.chunkSize * 0.3, startPos + config.minChunkSize);

    // Look for paragraph breaks first
    for (const marker of paragraphMarkers) {
      for (let i = searchEnd; i >= searchStart; i--) {
        if (text.substring(i, i + marker.length) === marker) {
          return i + marker.length;
        }
      }
    }

    // Look for sentence endings
    for (let i = searchEnd; i >= searchStart; i--) {
      if (sentenceEndings.includes(text[i]) && 
          i + 1 < text.length && 
          text[i + 1] === ' ') {
        return i + 1;
      }
    }

    // Look for word boundaries
    for (let i = searchEnd; i >= searchStart; i--) {
      if (text[i] === ' ') {
        return i + 1;
      }
    }

    // Fallback to exact position
    return Math.min(idealEnd, text.length);
  }

  function detectChunkType(content) {
    const trimmed = content.trim();
    if (structuralMarkers.heading.test(trimmed)) return 'heading';
    if (structuralMarkers.list.test(trimmed)) return 'list';
    if (structuralMarkers.table.test(trimmed)) return 'table';
    return 'paragraph';
  }

  while (currentPos < text.length) {
    const chunkStart = currentPos;
    const idealEnd = currentPos + config.chunkSize;
    const chunkEnd = findBestChunkBoundary(text, chunkStart, idealEnd);

    const chunkContent = text.slice(chunkStart, chunkEnd).trim();

    if (chunkContent.length >= config.minChunkSize) {
      const chunkType = detectChunkType(chunkContent);
      const wordCount = chunkContent.split(/\s+/).length;

      chunks.push({
        chunkIndex: chunkIndex,
        content: chunkContent,
        startPos: chunkStart,
        endPos: chunkEnd,
        length: chunkContent.length,
        wordCount: wordCount,
        chunkType: chunkType,
        metadata: {
          hasHeading: chunkType === 'heading',
          hasNumbers: /\d/.test(chunkContent),
          hasTurkishChars: /[çğıöşüÇĞIÖŞÜ]/.test(chunkContent),
          language: data.detectedLanguage || 'tr'
        }
      });
      chunkIndex++;
    }

    // Move to next chunk with overlap
    currentPos = Math.max(chunkEnd - config.chunkOverlap, chunkStart + config.minChunkSize);
    if (currentPos >= chunkEnd) break; // Prevent infinite loop
  }

  return chunks;
}

// Process the document
const chunks = intelligentChunking(text, config);

// Quality validation
const totalChunkLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
const averageChunkSize = totalChunkLength / chunks.length;

if (averageChunkSize < config.minChunkSize * 0.8) {
  console.warn('Average chunk size is below recommended minimum:', {
    averageSize: averageChunkSize,
    minSize: config.minChunkSize,
    totalChunks: chunks.length
  });
}

return [{
  json: {
    ...data,
    chunks: chunks,
    actualChunkCount: chunks.length,
    averageChunkSize: Math.round(averageChunkSize),
    chunkingQuality: {
      averageSize: averageChunkSize,
      sizeVariation: Math.max(...chunks.map(c => c.length)) - Math.min(...chunks.map(c => c.length)),
      structuralTypes: [...new Set(chunks.map(c => c.chunkType))]
    },
    chunkingTime: Date.now() - data.startTime - data.extractionTime,
    processingStatus: 'chunked'
  }
}];

// Enhanced embedding preparation with context
const documentData = $('Intelligent Document Chunking').item(0).json;
const batchData = $json;

// Get current batch of chunks
const currentBatch = documentData.chunks.slice(
  batchData.index * batchData.batchSize,
  (batchData.index + 1) * batchData.batchSize
);

// Enhanced embedding requests with context
const embeddingRequests = currentBatch.map(chunk => {
  // Add context for better embeddings
  const contextualContent = `Belge: ${documentData.filename}\n` +
    (chunk.chunkType === 'heading' ? 'Başlık: ' : '') +
    chunk.content;

  return {
    text: contextualContent,
    originalText: chunk.content,
    chunkId: `${documentData.documentId}_${chunk.chunkIndex}`,
    chunkIndex: chunk.chunkIndex,
    metadata: {
      documentId: documentData.documentId,
      filename: documentData.filename,
      wordCount: chunk.wordCount,
      startPos: chunk.startPos,
      endPos: chunk.endPos,
      chunkType: chunk.chunkType,
      detectedLanguage: documentData.detectedLanguage,
      qualityScore: calculateChunkQuality(chunk, documentData),
      ...chunk.metadata
    }
  };
});

// Function to calculate chunk quality score
function calculateChunkQuality(chunk, docData) {
  let score = 1.0;

  // Size quality
  const idealSize = docData.chunkingConfig.chunkSize;
  const sizeRatio = chunk.length / idealSize;
  if (sizeRatio < 0.5 || sizeRatio > 1.5) score *= 0.8;

  // Content quality
  if (chunk.wordCount < 10) score *= 0.7;
  if (chunk.metadata.hasTurkishChars) score *= 1.1; // Bonus for Turkish content
  if (chunk.chunkType === 'heading') score *= 1.2; // Bonus for structure

  return Math.min(score, 1.0);
}

return [{
  json: {
    ...documentData,
    currentBatch: currentBatch,
    embeddingRequests: embeddingRequests,
    batchIndex: batchData.index,
    totalBatches: Math.ceil(documentData.chunks.length / batchData.batchSize),
    batchQualityScore: embeddingRequests.reduce((sum, req) => sum + req.metadata.qualityScore, 0) / embeddingRequests.length
  }
}];

// Process embedding results with enhanced metadata
const embeddingResponse = $json;
const preparationData = $('Prepare Enhanced Embeddings').item(0).json;

// Validate embedding response
if (!embeddingResponse.data || !Array.isArray(embeddingResponse.data)) {
  throw new Error('Invalid embedding response from OpenAI');
}

if (embeddingResponse.data.length !== preparationData.embeddingRequests.length) {
  throw new Error(`Embedding count mismatch: expected ${preparationData.embeddingRequests.length}, got ${embeddingResponse.data.length}`);
}

// Combine embeddings with chunk data and enhanced metadata
const processedChunks = preparationData.embeddingRequests.map((request, index) => {
  const embedding = embeddingResponse.data[index];

  if (!embedding || !embedding.embedding) {
    throw new Error(`Missing embedding for chunk ${request.chunkIndex}`);
  }

  return {
    // Chunk data
    chunkIndex: request.chunkIndex,
    content: request.originalText,
    embedding: embedding.embedding,

    // Enhanced metadata
    metadata: {
      ...request.metadata,
      embeddingModel: 'text-embedding-ada-002',
      embeddingDimensions: embedding.embedding.length,
      processingTimestamp: new Date().toISOString(),
      batchIndex: preparationData.batchIndex,
      contextualText: request.text
    }
  };
});

// Calculate batch statistics
const batchStats = {
  processedChunks: processedChunks.length,
  totalTokensUsed: embeddingResponse.usage?.total_tokens || 0,
  averageQualityScore: preparationData.batchQualityScore,
  embeddingDimensions: processedChunks[0]?.embedding?.length || 1536
};

return [{
  json: {
    documentId: preparationData.documentId,
    customerId: preparationData.customerId,
    widgetId: preparationData.widgetId,
    batchIndex: preparationData.batchIndex,
    totalBatches: preparationData.totalBatches,
    processedChunks: processedChunks,
    batchStats: batchStats,
    processingStatus: 'embeddings_generated'
  }
}];

// Enhanced error handling and recovery
const error = $json.error || $execution.lastNodeExecuted?.error?.message || 'Unknown processing error';
const documentData = $('Parse Document Request').first()?.json || {};

// Detailed error logging
const errorDetails = {
  error: error,
  documentId: documentData.documentId,
  customerId: documentData.customerId,
  filename: documentData.filename,
  fileType: documentData.fileType,
  fileSize: documentData.fileSize,
  processingStage: $execution.lastNodeExecuted?.name || 'unknown',
  timestamp: new Date().toISOString(),
  processingVersion: '2.0'
};

console.error('Enhanced Document Processing Error:', errorDetails);

// Determine error category for better handling
let errorCategory = 'processing_error';
if (error.includes('timeout')) errorCategory = 'timeout_error';
else if (error.includes('file') || error.includes('download')) errorCategory = 'file_error';
else if (error.includes('embedding') || error.includes('OpenAI')) errorCategory = 'embedding_error';
else if (error.includes('database') || error.includes('Supabase')) errorCategory = 'database_error';

return [{
  json: {
    documentId: documentData.documentId,
    error: error,
    errorCategory: errorCategory,
    errorDetails: errorDetails,
    status: 'failed',
    timestamp: new Date().toISOString(),
    retryable: !['file_error', 'invalid_format'].includes(errorCategory)
  }
}];
